#include "Monstey_NavSeamMatcher.hpp"
#include "Monstey_Core.hpp"
#include <bit>
#include <cstring>
#include <iostream>
using namespace Monstey;
namespace {
using V=Monstey_NavSeamVector4;using J=Monstey_Json;using C=Monstey_NavSeamCandidate;
struct Mesh{Monstey_Bytes faces=Monstey_Bytes(16),edges=Monstey_Bytes(80),vertices=Monstey_Bytes(64);std::array<std::int32_t,1>fm{-1};std::array<std::int32_t,4>em{-1,-1,-1,-1};Monstey_NavigationAabb bounds{};Monstey_NavigationBoundaryMeshView View()const{Monstey_NavigationBoundaryMeshView m{};m.faces=faces;m.edges=edges;m.vertices=vertices;m.face_map=fm;m.edge_map=em;m.transform={V{1,0,0,0},V{0,1,0,0},V{0,0,1,0},V{0,0,0,0}};return m;}};
Mesh Quad(bool second){Mesh m;const std::array<V,4>p=second?std::array<V,4>{V{2,0,0,0},V{0,0,0,0},V{0,0,2,0},V{2,0,2,0}}:std::array<V,4>{V{0,0,0,0},V{2,0,0,0},V{2,0,-2,0},V{0,0,-2,0}};m.bounds=second?Monstey_NavigationAabb{V{0,0,0,0},V{2,0,2,0}}:Monstey_NavigationAabb{V{0,0,-2,0},V{2,0,0,0}};Monstey_PutU16(m.faces,8,4);for(unsigned i=0;i<4;++i){Monstey_PutU32(m.edges,i*20,i);Monstey_PutU32(m.edges,i*20+4,(i+1)%4);Monstey_PutU32(m.edges,i*20+8,0xffffffff);Monstey_PutU32(m.edges,i*20+12,0xffffffff);std::memcpy(m.vertices.data()+16*i,p[i].data(),16);}return m;}
C Candidate(unsigned b,float score,float low,float high){return C{0,0x400000u|b,0,0x400000u,score,1,1,true,{low,high,0,1}};}
}
int wmain(int argc,wchar_t**argv){try{Monstey_Require(argc==2,"Usage: NEW_REPORT");unsigned groups=0;auto Resolve=[&](std::vector<C>v){++groups;return Monstey_NavSeamResolveCandidates(v);};auto priority=Resolve({Candidate(1,.1f,0,1),Candidate(2,.01f,0,1)});Monstey_Require(!priority[0].enabled&&priority[1].enabled&&priority[1].edge_b==0x400002,"Native lowest-score priority differs");auto disjoint=Resolve({Candidate(1,.1f,0,.4f),Candidate(2,.01f,.6f,1)});Monstey_Require(disjoint[0].enabled&&disjoint[1].enabled,"Disjoint intervals were removed");auto trim=Resolve({Candidate(1,.1f,.495f,1),Candidate(2,.01f,0,.5f)});Monstey_Require(trim[0].enabled&&trim[1].enabled&&trim[0].intervals[0]==.5f,"Native small-overlap trim differs");auto overlap=Resolve({Candidate(1,.1f,.4f,1),Candidate(2,.01f,0,.5f)});Monstey_Require(!overlap[0].enabled&&overlap[1].enabled,"Native second-pass overlap removal differs");auto contained=Resolve({Candidate(1,.1f,0,1),Candidate(2,.01f,.2f,.4f)});Monstey_Require(!contained[0].enabled&&contained[1].enabled,"Native containment removal differs");auto tied=Resolve({Candidate(1,.1f,0,1),Candidate(2,.1f,0,1),Candidate(3,.1f,0,1)});Monstey_Require(tied[0].edge_b==0x400003&&tied[1].edge_b==0x400002&&tied[2].edge_b==0x400001&&tied[2].enabled&&!tied[0].enabled&&!tied[1].enabled,"Native equal-key quicksort/reverse-head priority differs");auto original=Quad(false),other=Quad(true);auto a=original.View(),b=other.View();std::array<std::uint8_t,6>leaf{};Monstey_NavigationCompactTreeView treeA{leaf,original.bounds},treeB{leaf,other.bounds};const V up{0,1,0,0};Monstey_NavSeamGroundSettings s{.5f,.1f,.01f,.0001f,.9f,.9f,.02f};auto Run=[&](const auto&av,const auto&bv,const auto&ta,const auto&tb){++groups;return Monstey_NavSeamMatchGroundMeshes(av,bv,original.bounds,other.bounds,ta,tb,up,.01f,s);};auto fast=Run(a,b,treeA,treeB);Monstey_Require(fast.connections==std::vector<Monstey_NavSeamConnection>{{0,0,0,0}}&&fast.coincident_connections==1&&fast.candidates.empty(),"Complete coincident ground path differs");auto shifted=b;shifted.transform[3]=V{1,0,0,0};auto partial=Run(a,shifted,treeA,treeB);Monstey_Require(partial.connections==std::vector<Monstey_NavSeamConnection>{{0,0,0,0}}&&partial.coincident_connections==0&&partial.candidates.size()==1&&partial.candidates[0].enabled,"Complete partial-overlap fallback path differs");Monstey_Require(std::abs(partial.candidates[0].intervals[0]-.5f)<.00001f&&partial.candidates[0].intervals[1]==1,"Partial native interval differs");shifted=b;shifted.transform[3]=V{10,0,0,0};auto absent=Run(a,shifted,treeA,treeB);Monstey_Require(absent.connections.empty(),"Disjoint whole meshes connected");std::array<std::uint8_t,18>duplicate{};duplicate[3]=0x80;duplicate[4]=1;Monstey_NavigationCompactTreeView repeatedA{duplicate,original.bounds},repeatedB{duplicate,other.bounds};auto repeat=Run(a,b,repeatedA,repeatedB);Monstey_Require(repeat.connections==fast.connections&&repeat.coincident_connections==1,"Duplicate tree hits defeated greedy used-edge exclusion");shifted=b;shifted.transform[3]=V{1,0,0,0};auto repeatPartial=Run(a,shifted,repeatedA,repeatedB);Monstey_Require(repeatPartial.connections==partial.connections&&repeatPartial.candidates.size()==4,"Duplicate fallback hits did not retain full candidate list and native conflict result");auto movedA=a,movedB=b;movedA.transform[3]=V{20,-3,8,0};movedB.transform[3]=movedA.transform[3];auto translated=Run(movedA,movedB,treeA,treeB);Monstey_Require(translated.connections==fast.connections,"Shared transform disconnected the native ground pair");Monstey_WriteNewText(argv[1],J::object({{"status","PASS"},{"groups",groups},{"native_program_called",false},{"process_accessed",false},{"scope","Ground-profile API regression under shared all-flag matcher; runtime-built owned trees, no native execution"},{"coincident_connections",fast.coincident_connections},{"fallback_connections",partial.connections.size()},{"duplicate_fallback_candidates",repeatPartial.candidates.size()}}).dump(2)+"\n");std::cout<<"PASS "<<groups<<" complete selected ground matcher groups\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}